styleSample:
/* RESET */

*{
margin:0;
padding:0;
box-sizing:border-box;
}

/* COLOR SYSTEM */

:root{

--primary-color:#7A1E1E;
--secondary-color:#C19A6B;
--bg-color:#F8F5F2;
--text-color:#333;

}

/* BODY */

body{
font-family:'Poppins',sans-serif;
background:var(--bg-color);
color:var(--text-color);
transition:0.4s;
}

/* CONTAINER */

.container{
width:95%;
max-width:1400px;
margin:auto;
}

/* HEADER */

.header{
background:white;
position:sticky;
top:0;
z-index:2000;
box-shadow:0 5px 20px rgba(0,0,0,0.08);
}

/* NAV WRAPPER */

.nav-wrapper{
display:flex;
align-items:center;
justify-content:space-between;
padding:18px 0;
min-height:64px;
}

/* LOGO */

/* .logo img{
width:160px;
} */
/* Logo container */
.logo-text{

display:flex;
align-items:center;
gap:10px;

font-size:18px;
font-weight:600;

text-decoration:ghostwhite;
color:#000000;

}

/* SPA ICON */

.logo-text i{

font-size:26px;

color:#c89b6e;

}

/* LOGO NAME */

.logo-text span{

font-family:"Poppins",sans-serif;

letter-spacing:0.5px;}
/* NAV MENU */

.nav-menu ul{
display:flex;
gap:30px;
list-style:none;
align-items:center;
}

.nav-menu a{
text-decoration:none;
font-weight:500;
color:#333;
position:relative;
}

.nav-menu .btn-login{
color:#fff;
}

/* HOVER */

.nav-menu a:hover{
color:var(--primary-color);
}

/* ACTIVE */

.nav-menu a.active{
color:var(--primary-color);
}

/* UNDERLINE EFFECT */

.nav-menu a::after{
content:"";
position:absolute;
left:0;
bottom:-5px;
width:0%;
height:2px;
background:var(--secondary-color);
transition:0.3s;
}

.nav-menu a:hover::after{
width:100%;
}

.nav-menu a.active::after{
width:100%;
}

/* DROPDOWN */
/* FIX DROPDOWN POSITION */

.dropdown{
position:relative;
}

.dropdown-menu{
position:absolute;
top:calc(100% + 30px);
left:0; /* ✅ FIXED */

background:white;
min-width:220px;

border-radius:8px;

box-shadow:0 10px 25px rgba(0,0,0,0.08);

opacity:0;
visibility:hidden;
transform:translateY(10px);
transition:0.3s;

flex-direction:column;
padding-left:0;
padding-right:0;
}

/* Home dropdown remove inner left/right spacing */
.nav-menu > ul > li.dropdown:first-child .dropdown-menu a{
padding-left:0;
padding-right:0;
}

.nav-menu > ul > li.dropdown:first-child .dropdown-menu{
padding-left:0;
padding-right:0;
}

.nav-menu > ul > li.dropdown:first-child .dropdown-menu li a{
padding-left:0 !important;
padding-right:0 !important;
}

/* SHOW ON HOVER (DESKTOP) */

.dropdown:hover .dropdown-menu{
opacity:1;
visibility:visible;
transform:translateY(0);
}

