position:absolute;
top:100%;
left:200px;
background:white;
list-style:none;
min-width:250px;
border-radius:8px;
box-shadow:0 10px 25px rgba(0,0,0,0.08);
opacity:0;
visibility:hidden;
transform:translateY(10px);
transition:0.3s;
display: flex;
