transform:translateY(0);
}

.dropdown-menu a{
display:block;
padding:7px 20px;
}

.dropdown-menu a:hover{
background:#f3f3f3;
} */

/* ACTION BUTTONS */

.nav-actions{
display:flex;
align-items:center;
gap:20px;
}

.mobile-actions{
display:none;
gap:12px;
align-items:center;
justify-content:center;
margin-top:10px;
}

.mobile-login{
display:none;
width:100%;
}

.mobile-actions .icon-btn{
width:40px;
height:40px;
border-radius:10px;
background:#f3f3f3;
display:flex;
align-items:center;
justify-content:center;
}

.icon-btn{
border:none;
background:none;
font-size:18px;
cursor:pointer;
}

.btn-login{
padding:8px 20px;
background:var(--primary-color);
color:white;
text-decoration:none;
border-radius:6px;
transition:0.3s;
}

.btn-login:hover{
background:#5d1515;
}

/* HAMBURGER */

.hamburger{
display:none;
font-size:24px;
cursor:pointer;
}
@media(max-width:1100px){
  .nav-menu ul{
    gap:18px;
  }
  .nav-menu a{
    font-size:14px;
  }
  .nav-actions{
    gap:12px;
  }
  .btn-login{
    padding:6px 14px;
  }
  .logo-text span{
    font-size:16px;
  }
}
@media(max-width:400px){
  .logo-text span{
    white-space:nowrap;
    font-size:15px;
  }
}
@media(max-width:900px){

/* SHOW HAMBURGER */
.hamburger{
display:block;
}

.logo{
order:1;
}

.nav-actions{
display:none;
}

.hamburger{
order:2;
}

/* NAV MENU MOBILE */
.nav-menu{
position:absolute;
top:70px;
left:0;
width:100%;
background:white;

display:none;
flex-direction:column;
padding:20px;
order:4;
max-height:calc(100vh - 90px);
overflow-y:auto;
-webkit-overflow-scrolling:touch;
}

/* Fixed header on mobile/tablet */
body{
padding-top:72px;
}

.header{
position:fixed;
top:0;
width:100%;
left:0;
right:0;
}

/* ACTIVE MENU */
.nav-menu.active{
display:flex;
}

/* STACK ITEMS */
.nav-menu ul{
flex-direction:column;
gap:15px;
align-items:flex-start;
}

/* DROPDOWN MOBILE */
.dropdown-menu{
position:static;
box-shadow:none;
opacity:1;
visibility:visible;
display:none;
transform:none;
}

/* SHOW DROPDOWN ON CLICK */
.dropdown.active .dropdown-menu{
display:block;
}

/* MOBILE ACTIONS */
.mobile-login{
display:block;
}

.mobile-login .btn-login{
display:block;
width:100%;
text-align:center;
}

.mobile-actions{
display:flex;
width:100%;
justify-content:center;
padding-top:8px;
}
}
/* ================= HERO SECTION ================= */

.hero{

padding:80px 0;
background:linear-gradient(135deg,#f8f5f2,#ffffff);

}

.hero-container{

display:grid;
grid-template-columns:1fr 1fr;
align-items:center;
gap:60px;

}

/* HERO TEXT */

.hero-tag{

background:#C19A6B;
color:white;
padding:6px 14px;
border-radius:20px;
font-size:14px;
display:inline-block;
margin-bottom:20px;

}

.hero-content h1{

font-size:48px;
line-height:1.2;
margin-bottom:20px;
font-family:'Merriweather',serif;

}

.hero-content h1 span{

color:#7A1E1E;

}

.hero-content p{

color:#555;
margin-bottom:30px;
font-size:16px;
line-height:1.6;

}

/* HERO BUTTONS */

.hero-buttons{

display:flex;
gap:15px;

}

.btn-primary{

background:#7A1E1E;
color:white;
padding:12px 24px;
border-radius:6px;
text-decoration:none;
font-weight:500;
transition:0.3s;

}

.btn-primary:hover{

background:#5e1414;
transform:translateY(-3px);

}

.btn-secondary{

border:2px solid #7A1E1E;
padding:12px 24px;
border-radius:6px;
text-decoration:none;
color:#7A1E1E;
font-weight:500;
transition:0.3s;

}

.btn-secondary:hover{

background:#7A1E1E;
color:white;

}

/* ================= BOOK CARDS ================= */

.hero-books{

display:grid;
grid-template-columns:repeat(3,1fr);
gap:20px;

}

.book-card{

position:relative;
border-radius:12px;
overflow:hidden;
box-shadow:0 10px 30px rgba(0,0,0,0.1);
transition:0.4s;

}

.book-card img{

width:100%;
height:260px;
object-fit:cover;
transition:0.4s;

}

.book-card:hover img{

transform:scale(1.1);

}

.book-card:hover{

transform:translateY(-10px);

}

/* BOOK INFO */

.book-info{

position:absolute;
bottom:0;
left:0;
width:100%;
padding:15px;
background:linear-gradient(transparent,rgba(0,0,0,0.8));
color:white;

}

.book-info h4{

font-size:16px;

}

.book-info span{

font-size:13px;
opacity:0.8;

}
@media(max-width:900px){
  .hero{
    padding:70px 0;
  }

  .hero-container{
    grid-template-columns:1fr;
    gap:30px;
  }

  .hero-books{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  .hero-content h1{
    font-size:38px;
  }
}

@media(max-width:600px){
  .hero{
    padding:60px 0;
  }

  .hero-books{
    grid-template-columns:1fr;
  }

  .hero-content h1{
    font-size:32px;
  }

  .hero-buttons{
    flex-direction:column;
    align-items:stretch;
  }

  .hero-buttons a{
    width:100%;
    text-align:center;
  }
}
/* ================= FEATURED BOOKS ================= */

.featured-books{
padding:80px 0;
background:#ffffff;
}

/* SECTION HEADER */

.section-header{
text-align:center;
margin-bottom:40px;
}

.section-header h2{
font-size:36px;
font-family:'Merriweather',serif;
color:#7A1E1E;
margin-bottom:10px;
}

.section-header p{
color:#666;
max-width:600px;
margin:auto;
}

/* FILTER BUTTONS */

.book-filters{
display:flex;
justify-content:center;
gap:15px;
margin-bottom:40px;
flex-wrap:wrap;
}

.filter-btn{
border:1px solid #7A1E1E;
padding:8px 18px;
background:white;
cursor:pointer;
border-radius:20px;
transition:0.3s;
}

.filter-btn.active,
.filter-btn:hover{
background:#7A1E1E;
color:white;
}

/* BOOK GRID */

.books-grid{
display:grid;
grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
gap:30px;
}

/* BOOK CARD */

.book-item{
background:white;
border-radius:12px;
overflow:hidden;
box-shadow:0 10px 25px rgba(0,0,0,0.08);
transition:0.4s;
}

.book-item:hover{
transform:translateY(-10px);
}

/* IMAGE */

.book-image img{
width:100%;
height:260px;
object-fit:cover;
transition:0.4s;
}

.book-item:hover img{
transform:scale(1.08);
}

/* DETAILS */

.book-details{
padding:18px;
}

.book-details h3{
font-size:18px;
margin-bottom:5px;
}

.author{
font-size:14px;
color:#777;
display:block;
margin-bottom:10px;
}

/* RATING */

.rating{
color:#f5b50a;
margin-bottom:12px;
}

/* FOOTER */

.book-footer{
display:flex;
justify-content:space-between;
align-items:center;
}

.price{
font-weight:600;
color:#7A1E1E;
}

.book-actions a{
margin-left:10px;
color:#555;
font-size:16px;
transition:0.3s;
}

.book-actions a:hover{
color:#7A1E1E;
}
/* ================= STAFF PICKS ================= */

.staff-picks{
padding:80px 0;
background:#f8f5f2;
}

.staff-grid{
display:grid;
grid-template-columns:repeat(auto-fit,minmax(300px,1fr));
gap:30px;
}

/* CARD */

.staff-card{
display:flex;
gap:20px;
background:white;
padding:20px;
border-radius:12px;
box-shadow:0 10px 25px rgba(0,0,0,0.08);
transition:0.4s;
align-items:stretch;
}

.staff-card:hover{
transform:translateY(-10px);
}

/* BOOK IMAGE */

.staff-book img{
width:110px;
height:160px;
object-fit:cover;
border-radius:8px;
}

/* INFO */

.staff-info h3{
font-size:18px;
margin-bottom:4px;
}

.staff-info .author{
font-size:14px;
color:#777;
display:block;
margin-bottom:10px;
}

/* REVIEW */

.staff-review{
font-size:14px;
color:#555;
margin-bottom:15px;
}

.staff-info{
display:flex;
flex-direction:column;
justify-content:space-between;
flex:1;
}

.staff-review{
min-height:66px;
}

/* STAFF MEMBER */

.staff-member{
display:flex;
align-items:center;
gap:10px;
margin-top:auto;
}

.staff-member img{
width:40px;
height:40px;
border-radius:50%;
object-fit:cover;
}

.staff-member h4{
font-size:14px;
margin-bottom:2px;
}

.staff-member span{
font-size:12px;
color:#888;
}
/* ================= BOOK CATEGORIES ================= */

.book-categories{
padding:80px 0;
background:#fff;
}

/* WRAPPER */

.categories-wrapper{

display:grid;
grid-template-columns:1fr 1fr;
gap:40px;
margin-top:40px;

}

/* COLUMN */

.category-column{

display:flex;
flex-direction:column;
gap:20px;

}

/* CARD */

.category-card{

display:flex;
align-items:center;
gap:20px;
padding:20px;
border-radius:10px;
background:#f8f5f2;
border:1px solid #eee;
transition:0.4s;
cursor:pointer;

}

.category-card:hover{

transform:translateY(-5px);
background:#7A1E1E;
color:#fff;
box-shadow:0 10px 20px rgba(0,0,0,0.1);

}

/* ICON */

.category-icon{

font-size:24px;
color:#7A1E1E;
transition:0.3s;

}

.category-card:hover .category-icon{

color:#fff;

}

/* TEXT */

.category-card h3{

font-size:18px;

}

.category-card span{

font-size:14px;
color:#777;

}

.category-card:hover span{

color:#f3f3f3;

}
/* =========================
   TABLET RESPONSIVE
========================= */

@media(max-width:992px){

.categories-wrapper{
grid-template-columns:1fr; /* ✅ stack columns */
gap:30px;
}

.category-card{
padding:18px;
}

.category-card h3{
font-size:17px;
}

}


/* =========================
   MOBILE RESPONSIVE
========================= */

@media(max-width:600px){

.book-categories{
padding:60px 0;
}

/* SINGLE COLUMN */
.categories-wrapper{
grid-template-columns:1fr;
gap:20px;
}

/* CARD DESIGN */
.category-card{
padding:16px;
gap:15px;
border-radius:8px;
}

/* ICON SMALL */
.category-icon{
font-size:20px;
}

/* TEXT */
.category-card h3{
font-size:16px;
}

.category-card span{
font-size:13px;
}

/* REMOVE HEAVY HOVER ON MOBILE */
.category-card:hover{
transform:none;
box-shadow:none;
}

}
/* ================= TESTIMONIALS ================= */

.testimonials{
padding:80px 0;
background:#f8f5f2;
}

/* GRID */

.testimonial-grid{
display:grid;
grid-template-columns:repeat(auto-fit,minmax(280px,1fr));
gap:30px;
margin-top:40px;
}

/* CARD */

.testimonial-card{

background:white;
padding:25px;
border-radius:12px;
box-shadow:0 10px 25px rgba(0,0,0,0.08);
transition:0.4s;

}

.testimonial-card:hover{

transform:translateY(-10px);

}

/* TEXT */

.testimonial-text p{

font-size:15px;
color:#555;
line-height:1.6;
margin-bottom:15px;

}

/* RATING */

.testimonial-rating{

color:#f5b50a;
margin-bottom:15px;

}

/* USER */

.testimonial-user{

display:flex;
align-items:center;
gap:12px;

}

.testimonial-user img{

width:45px;
height:45px;
border-radius:50%;
object-fit:cover;

}

.testimonial-user h4{

font-size:15px;
margin-bottom:2px;

}

.testimonial-user span{

font-size:13px;
color:#777;

}
/* ================= GALLERY STRIP ================= */

.gallery-strip{
padding:80px 0;
background:#ffffff;
}

.gallery-grid{
display:grid;
grid-template-columns:repeat(4,1fr);
gap:18px;
margin-top:30px;
}

.gallery-grid img{
width:100%;
height:180px;
object-fit:cover;
border-radius:14px;
box-shadow:0 10px 25px rgba(0,0,0,0.1);
transition:0.35s;
}

.gallery-grid img:hover{
transform:translateY(-6px);
box-shadow:0 18px 35px rgba(0,0,0,0.18);
}

@media(max-width:1000px){
  .gallery-grid{
    grid-template-columns:repeat(2,1fr);
  }
}

@media(max-width:600px){
  .gallery-grid{
    grid-template-columns:1fr;
  }
  .gallery-grid img{
    height:200px;
  }
}
/* Author Events Section */

.author-events{
  padding:80px 0;
  background:#f9fafc;
  text-align:center;
}

.container{
  max-width:1200px;
  margin:auto;
}

.section-title{
  font-size:36px;
  margin-bottom:10px;
}

.section-subtitle{
  color:#666;
  margin-bottom:50px;
}

/* Grid */

.events-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:25px;
}

/* Card */

.event-card{
  background:#fff;
  border-radius:12px;
  overflow:hidden;
  box-shadow:0 6px 15px rgba(0,0,0,0.08);
  transition:0.4s;
  display:flex;
  flex-direction:column;
}

.event-card img{
  width:100%;
  height:200px;
  object-fit:cover;
}

/* Content */

.event-content{
  padding:20px;
  text-align:left;
  display:flex;
  flex-direction:column;
  flex:1;
  gap:15px;
}

.event-content h3{
  margin-bottom:0;
}

.event-date{
  font-size:14px;
  color:#7A1E1E;
  font-weight:600;
  margin-bottom:0;
}

.event-content p{
  margin:0;
}

.author-events .event-date{
  background:none;
  color:#7A1E1E;
}

/* Button */

.event-btn{
  display:inline-block;
  margin-top:10px;
  padding:8px 18px;
  background:#7A1E1E;
  color:#fff;
  text-decoration:none;
  border-radius:6px;
  transition:0.3s;
  margin-top:auto;
}

.event-btn:hover{
  background:#7A1E1E;
}

/* Hover Effect */

.event-card:hover{
  transform:translateY(-8px);
  box-shadow:0 12px 25px rgba(0,0,0,0.15);
}
@media(max-width:1000px){

  .events-grid{
    grid-template-columns:repeat(2,1fr);
  }

}

@media(max-width:600px){

  .events-grid{
    grid-template-columns:1fr;
  }

}
/* Newsletter Section */

.newsletter{
  padding:80px 8%;
  background:linear-gradient(135deg,#4b6cb7,#182848);
  text-align:center;
  color:#fff;
}

.newsletter-container{
  max-width:700px;
  margin:auto;
}

.newsletter-title{
  font-size:36px;
  margin-bottom:15px;
}

.newsletter-text{
  margin-bottom:30px;
  opacity:0.9;
}

/* Form */

.newsletter-form{
  display:flex;
  justify-content:center;
  gap:10px;
  flex-wrap:wrap;
}

.newsletter-form input{
  padding:12px 15px;
  width:300px;
  border:none;
  border-radius:6px;
  outline:none;
  font-size:16px;
}

.newsletter-form button{
  padding:12px 25px;
  border:none;
  border-radius:6px;
  background:#ff7a18;
  color:#fff;
  font-size:16px;
  cursor:pointer;
  transition:0.3s;
}

.newsletter-form button:hover{
  background:#ff5400;
  transform:translateY(-2px);
}
@media(max-width:600px){

.newsletter-form{
flex-direction:column;
}

.newsletter-form input{
width:100%;
}

.newsletter-form button{
width:100%;
}

}
/* Footer */

.footer{
  background:#111;
  color:#ddd;
  padding:60px 8% 20px;
}

.footer-container{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:40px;
}

.footer-col h4{
  margin-bottom:20px;
}

.footer-logo{
  font-size:24px;
  margin-bottom:15px;
}

.footer-brand{
  display:inline-flex;
  align-items:center;
  gap:10px;
  text-decoration:none;
  color:#ddd;
}

.footer-brand i{
  color:#C19A6B;
}

.footer-brand:hover{
  color:#fff;
}

.footer-col p{
  line-height:1.6;
}

.footer-col ul{
  list-style:none;
  padding:0;
}

.footer-col ul li{
  margin-bottom:10px;
}

.footer-col ul li a{
  color:#bbb;
  text-decoration:none;
  transition:0.3s;
}

.footer-col ul li a:hover{
  color:#fff;
  padding-left:5px;
}

/* Social Icons */

.social-icons{
  display:flex;
  gap:15px;
}

.social-icons a{
  width:35px;
  height:35px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:#222;
  border-radius:50%;
  color:#fff;
  transition:0.3s;
}

.social-icons a:hover{
  background:#ff7a18;
  transform:translateY(-3px);
}

/* Bottom */

.footer-bottom{
  text-align:center;
  border-top:1px solid #333;
  margin-top:40px;
  padding-top:20px;
