.h

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary-color: #f84c07;
  --heading-font: "Josefin Sans", sans-serif;
  --body-font: "Poppins", sans-serif;
  --secondary-font: "Roboto", sans-serif;
  --header-height: 78px;
}

body {
  font-family: var(--body-font);
  background: #ffffff;
  color: #333;
  transition: all 0.4s ease;
  overflow-x: hidden;
}

body.has-header{
  padding-top: var(--header-height);
}

html {
  overflow-x: hidden;
  overflow-y: scroll;
  scrollbar-gutter: stable;
}

h1,
h2,
h3,
h4,
h5,
h6,
.logo-text,
.logo-text-fot {
  font-family: var(--heading-font);
}

body,
.header,
.footer,
.nav-menu a,
.dropdown-menu
.popular-dishes,
.truck-schedule,
.dish-card,
.schedule-card {
  transition: background-color 0.4s ease,
              color 0.4s ease,
              border-color 0.4s ease;
}
section h2 {
  font-size: 38px;
  font-weight: 700;
  text-align: center;
  margin-bottom: 15px;

  background: var(--primary-color);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.section-heading p{
    text-align: center;
    margin-bottom: 30px;
}
/* ================= CONTAINER ================= */
.container {
  width: 95%;
  max-width: 1400px;
  margin: auto;
}

/* ================= HEADER ================= */
.header {
  background: #fff;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 2000;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
}

/* ================= NAV WRAPPER ================= */
.nav-wrapper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 0;
  transition: all 0.4s ease;
}

.nav-menu {
  flex: 1;
  display: flex;
  justify-content: center;
  transition: all 0.4s ease;
}

.nav-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 20px;
  transition: all 0.4s ease;
}


/* ================= NAVIGATION ================= */
.nav-menu > ul {
  display: flex;
  gap: 30px;
  list-style: none;
  align-items: center;
  transition: all 0.4s ease;
}

.nav-menu li {
  position: relative;
}

.nav-menu a {
  text-decoration: none;
  color: #333;
  font-weight: 500;
  position: relative;
  padding-bottom: 4px;
  transition: background-color 0.4s ease,
              color 0.4s ease,
              box-shadow 0.4s ease;
}

.nav-menu a:hover {
  color: var(--primary-color);
}

/* Underline Animation */
.nav-menu > ul > li > a::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0%;
  height: 2px;
  background: var(--primary-color);
  transition: 0.3s;
}

.nav-menu > ul > li > a:hover::after {
  width: 100%;
}


/* ================= DROPDOWN ================= */
.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  background: #fff;
  min-width: 200px;
  border-radius: 8px;
  padding: 10px 0;
  list-style: none;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: 0.3s ease;
}

.dropdown:hover .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.dropdown-menu a {
  display: block;
  padding: 10px 20px;
  font-size: 14px;
  transition: 0.3s ease;
}

.dropdown-menu a:hover {
  background: #f3f4f6;
  padding-left: 28px;
}

.arrow {
  font-size: 12px;
  margin-left: 5px;
  transition: 0.3s;
}

.dropdown:hover .arrow {
  transform: rotate(180deg);
}

/* ================= ACTION BUTTONS ================= */
.icon-btn {
  background: none;
  border: none;
  font-size: 18px;
  cursor: pointer;
}

.icon-btn i {
  color: #333;
  transition: 0.3s ease;
}

.icon-btn:hover i {
  color: var(--primary-color);
}

.btn-login {
  padding: 8px 20px;
  background: var(--primary-color);
  color: #fff;
  border-radius: 6px;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  transition: background-color 0.4s ease,
              color 0.4s ease,
              box-shadow 0.4s ease;
}

.btn-login:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(131, 74, 66, 0.4);
}

/* ================= ACTIVE MENU ================= */
.nav-menu a.active{
  color:var(--primary-color) !important;
  font-weight:inherit;
}

.nav-menu a.active::after{
  width:100%;
  height:2px;
  background:var(--primary-color);
}
/* ================= HAMBURGER ================= */
.hamburger {
  display: none;
  font-size: 24px;
  cursor: pointer;
}
.menu-close{
    display: none;
}
.logo a{
display:flex;
align-items:center;
gap:10px;
text-decoration:none;
}
