/* swipe

:root {
  --page-bg: 248 250 252;
  --text: 15 23 42;
  --muted: 100 116 139;
  --border: 148 163 184;
  --glass: 255 255 255;
  --glass-alpha: 0.72;
  --accent: 236 72 153;
  --heading: 10 15 29;
  --button-bg: 236 72 153;
  --button-bg-hover: 219 39 119;
  --button-text: 255 255 255;
  --button-border: 236 72 153;
  --button-outline-text: 15 23 42;
  --font-sans: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
  --font-display: "Playfair Display", "Times New Roman", serif;
  --surface: 255 255 255;
  --surface-alt: 250 247 244;
  --ink-soft: 30 41 59;
  --shadow-soft: 0 24px 55px -40px rgba(15, 23, 42, 0.35);
  --shadow-lift: 0 30px 65px -42px rgba(15, 23, 42, 0.45);
  --section-pad: 110px;
  --section-pad-md: 90px;
  --section-pad-sm: 70px;
  --section-gap: 28px;
  --section-title-margin: 56px;
  --fs-body: 1rem;
  --fs-sm: 0.925rem;
  --fs-lg: 1.125rem;
  --fs-h1: clamp(2.6rem, 2.2rem + 1.8vw, 4rem);
  --fs-h2: clamp(2rem, 1.7rem + 1.2vw, 3rem);
  --fs-h3: clamp(1.4rem, 1.2rem + 0.6vw, 2rem);
  --fs-h4: clamp(1.1rem, 1rem + 0.3vw, 1.35rem);
  --lh-body: 1.7;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  margin: 0;
  padding: 0;
  background: radial-gradient(circle at top, rgba(236, 72, 153, 0.04), transparent 55%),
    linear-gradient(180deg, rgba(248, 250, 252, 0.95) 0%, rgba(244, 240, 236, 0.95) 100%);
  color: rgb(var(--text));
  font-size: var(--fs-body);
  line-height: var(--lh-body);
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: rgb(var(--heading));
  letter-spacing: -0.02em;
  font-family: var(--font-display);
  line-height: 1.18;
}

h1 {
  font-size: var(--fs-h1);
}

h2 {
  font-size: var(--fs-h2);
}

h3 {
  font-size: var(--fs-h3);
}

h4 {
  font-size: var(--fs-h4);
}

p,
li,
span {
  color: rgb(var(--text));
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.65rem 1.25rem;
  border-radius: 9999px;
  font-weight: 600;
  line-height: 1;
  font-size: 0.95rem;
  transition: transform 200ms ease, box-shadow 200ms ease, background-color 200ms ease,
    color 200ms ease, border-color 200ms ease;
}

.btn-primary {
  background: rgb(var(--button-bg));
  color: rgb(var(--button-text));
  border: 1px solid rgb(var(--button-border));
  box-shadow: 0 18px 35px -22px rgb(var(--accent) / 0.75);
}

.btn-primary:hover {
  background: rgb(var(--button-bg-hover));
  color: rgb(var(--button-text));
  transform: translateY(-2px);
  box-shadow: 0 22px 48px -26px rgb(var(--accent) / 0.85);
}

.btn-outline {
  background: transparent;
  color: rgb(var(--button-outline-text));
  border: 1px solid rgb(var(--border) / 0.3);
}

.btn-outline:hover {
  border-color: rgb(var(--button-border));
  color: rgb(var(--button-border));
}

#site-header.is-scrolled #nav-surface {
  background: rgb(var(--glass) / 0.9);
  box-shadow: 0 30px 70px -45px rgba(15, 23, 42, 0.6);
}

[data-dropdown].is-open [data-dropdown-menu],
[data-dropdown]:hover [data-dropdown-menu],
[data-dropdown]:focus-within [data-dropdown-menu] {
  pointer-events: auto;
  opacity: 1;
  transform: translateY(0);
}

.nav-link {
  position: relative;
}

.nav-link.active {
  color: rgb(var(--accent));
}

.nav-link.active span,
.nav-link.active::after {
  transform: scaleX(1);
}

.nav-link.active::after {
  content: "";
  position: absolute;
  left: 16px;
  right: 16px;
  bottom: -4px;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgb(var(--accent)), rgba(var(--accent), 0.4));
}

.nav-link.is-active {
  color: rgb(var(--accent));
}

#theme-toggle,
.cd-icon-btn {
  position: relative;
  overflow: hidden;
}

#theme-toggle .theme-icon,
.cd-icon-btn .theme-icon {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: none;
}

#theme-toggle .theme-icon i,
.cd-icon-btn .theme-icon i {
  font-size: 1rem;
}

#theme-toggle .icon-sun,
.cd-icon-btn .icon-sun {
  opacity: 0;
  transform: translateY(6px);
}

[data-theme="dark"] #theme-toggle .icon-moon,
body.dark .cd-icon-btn .icon-moon {
  opacity: 0;
  transform: translateY(-6px);
}

[data-theme="dark"] #theme-toggle .icon-sun,
body.dark .cd-icon-btn .icon-sun {
  opacity: 1;
  transform: translateY(0);
}

#theme-toggle .icon-moon,
.cd-icon-btn .icon-moon {
  opacity: 1;
  transform: translateY(0);
}


#mobile-menu.is-open {
  pointer-events: auto;
  opacity: 1;
}

#mobile-menu.is-open > div {
  transform: translateX(0);
}


/* =========================
   ROOT VARIABLES
========================= */
:root {
  --primary: rgb(var(--accent));
  --secondary: #f5efe6;
  --text: 15 23 42;
  --white: #ffffff;
  --border: 148 163 184;
}

/* =========================
   GLOBAL
========================= */
body {
  font-family: var(--font-sans);
  background: radial-gradient(circle at top, rgba(236, 72, 153, 0.04), transparent 55%),
    linear-gradient(180deg, rgba(248, 250, 252, 0.95) 0%, rgba(244, 240, 236, 0.95) 100%);
  color: rgb(var(--text));
  margin: 0;
}

h1 {
  font-family: var(--font-display);
}

/* .container {
  width: 90%;
  max-width: 1200px;
  margin: auto;
} */
/* GLOBAL CONTAINER */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px; /* LEFT + RIGHT SPACE */
}

/* =========================
   HERO SECTION
========================= */
.hero {
  padding: 90px 0;
  padding-top: 50px;
  background: linear-gradient(135deg, #f5efe6, #f0e7dc);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  width: 400px;
  height: 400px;
  background: rgba(255,255,255,0.4);
  filter: blur(120px);
  top: -100px;
  left: -100px;
}

.hero-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 50px;
}

/* LEFT CONTENT */
.hero-content {
  flex: 1;
}

.hero-badge {
  display: inline-block;
  padding: 6px 14px;
  background: rgba(255,255,255,0.6);
  backdrop-filter: blur(10px);
  border-radius: 30px;
  font-size: 14px;
  margin-bottom: 20px;
}

.hero h1 {
  font-size: 52px;
  line-height: 1.2;
  margin-bottom: 20px;
}

.hero h1 span {
  color: var(--primary);
}

.hero p {
  font-size: 16px;
  margin-bottom: 30px;
  max-width: 500px;
}

/* BUTTONS */
.btn {
  padding: 12px 28px;
  border-radius: 30px;
  text-decoration: none;
  font-weight: 500;
  transition: 0.3s ease;
  display: inline-block;
}

.btn-primary {
  background: rgb(var(--accent));
  color: #fff;
}

.btn-primary:hover {
  background: rgb(var(--button-bg-hover));
  transform: translateY(-2px);
}

.btn-secondary {
  border: 1px solid rgb(var(--accent) / 0.35);
  margin-left: 10px;
  color: rgb(var(--accent));
}

.btn-secondary:hover {
  background: rgb(var(--accent) / 0.08);
}

/* RIGHT IMAGE */
.hero-image {
  flex: 1;
  position: relative;
}

.hero-image img {
  width: 100%;
  border-radius: 20px;
  transition: transform 0.5s ease;
}

.hero-image:hover img {
  transform: scale(1.05);
}

/* FLOATING CARDS */
.floating-card {
  position: absolute;
  background: rgba(255,255,255,0.7);
  backdrop-filter: blur(12px);
  padding: 10px 16px;
  border-radius: 12px;
  font-size: 14px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
}

.card-1 {
  top: 20px;
  left: -20px;
}

.card-2 {
  bottom: 20px;
  right: -20px;
}

/* =========================
   RESPONSIVE
========================= */
@media (max-width: 992px) {
  .hero-container {
    flex-direction: column;
    text-align: center;
  }

  .hero-buttons {
    justify-content: center;
  }

  .hero-image {
    margin-top: 40px;
  }
}

@media (max-width: 600px) {
  .hero h1 {
    font-size: 34px;
  }

  .btn {
    padding: 10px 20px;
  }
}


/* TRUST SECTION */
.trust {
  padding: 90px 0;
  text-align: center;
  background: #fff;
}

.trust-title {
  font-size: 30px;
  margin-bottom: 20px;
  font-family: 'Playfair Display', serif;
}

/* RATING */
.trust-rating {
  margin-bottom: 40px;
}

.stars {
  color: #f5a623;
  font-size: 24px;
  letter-spacing: 4px;
}

.trust-rating p {
  color: #666;
}

/* LOGOS */
.trust-logos {
  display: flex;
  justify-content: center;
  gap: 50px;
  flex-wrap: wrap;
  margin-bottom: 60px;
}

.trust-logos img {
  width: 90px;
  filter: grayscale(100%);
  opacity: 0.6;
  transition: all 0.4s ease;
}

.trust-logos img:hover {
  filter: grayscale(0%);
  opacity: 1;
  transform: translateY(-6px) scale(1.05);
}

/* TESTIMONIALS */
.trust-testimonials {
  display: flex;
  justify-content: center;
  gap: 25px;
  flex-wrap: wrap;
}

.trust-center {
  text-align: center;
}

.trust-center .trust-logos,
.trust-center .trust-testimonials {
  justify-content: center;
  margin-left: auto;
  margin-right: auto;
}

.trust-center .trust-title,
.trust-center .trust-rating,
.trust-center .trust-text {
  text-align: center;
  margin-left: auto;
  margin-right: auto;
}

.trust-center .trust-logos {
  width: 100%;
  align-items: center;
}

.trust-center .container {
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

.trust-center-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.trust-center-inner > * {
  width: 100%;
}

.testimonial-card {
  background: #fafafa;
  padding: 25px;
  border-radius: 18px;
  max-width: 260px;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0,0,0,0.05);
  transition: all 0.3s ease;
}

.testimonial-card:hover {
  transform: translateY(-10px);
  box-shadow: 0 25px 60px rgba(0,0,0,0.12);
}

/* AVATAR */
.testimonial-card img {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  margin-bottom: 15px;
  object-fit: cover;
  transition: 0.3s ease;
}

.testimonial-card:hover img {
  transform: scale(1.1);
}

/* TEXT */
.testimonial-card p {
  font-size: 14px;
  margin-bottom: 10px;
}

.testimonial-card span {
  font-size: 13px;
  color: #888;
}

/* RESPONSIVE */
@media (max-width: 768px) {
  .trust-title {
    font-size: 24px;
  }

  .trust-logos img {
    width: 70px;
  }
}


/* =========================
   CATEGORIES SECTION
========================= */
.categories {
  padding: 90px 0;
  background: linear-gradient(180deg, rgba(255,255,255,0.6) 0%, rgba(245,240,235,0.6) 100%);
}

.categories-container {
  padding-left: 20px;
  padding-right: 20px;
}

.section-title {
  text-align: center;
  font-size: 32px;
  margin-bottom: 50px;
  font-family: 'Playfair Display', serif;
  color: rgb(var(--heading));
  letter-spacing: -0.02em;
}

/* GRID */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 25px;
}

/* CARD */
.category-card {
  position: relative;
  overflow: hidden;
  border-radius: 22px;
  cursor: pointer;
  background: rgb(var(--glass) / 0.6);
  border: 1px solid rgb(var(--border) / 0.18);
  box-shadow: 0 20px 50px -35px rgba(15, 23, 42, 0.35);
  transition: transform 0.35s ease, box-shadow 0.35s ease;
}

/* IMAGE */
.category-card img {
  width: 100%;
  height: 300px;
  object-fit: cover;
  transition: transform 0.6s ease, filter 0.6s ease;
}

/* OVERLAY */
.overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(7, 11, 20, 0.75), rgba(7, 11, 20, 0.2));
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  padding: 0 28px 30px;
  color: #fff;
  transition: 0.4s ease;
  text-shadow: 0 12px 30px rgba(0,0,0,0.35);
}

/* TITLE */
.overlay h3 {
  font-size: 24px;
  margin-bottom: 8px;
  color: #fff;
}

.category-meta {
  margin-bottom: 14px;
  font-size: 13px;
  color: rgba(255,255,255,0.85);
}

/* BUTTON */
.overlay .btn {
  padding: 10px 24px;
  border-radius: 30px;
  background: rgb(var(--glass));
  color: rgb(var(--heading));
  text-decoration: none;
  font-size: 14px;
  opacity: 0;
  transform: translateY(15px);
  transition: 0.3s ease;
}

/* HOVER EFFECT */
.category-card:hover img {
  transform: scale(1.12);
  filter: saturate(1.08);
}

.category-card:hover .overlay {
  background: linear-gradient(to top, rgba(7, 11, 20, 0.88), rgba(7, 11, 20, 0.3));
}

.category-card:hover .overlay .btn {
  opacity: 1;
  transform: translateY(0);
}

.category-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 26px 60px -36px rgba(15, 23, 42, 0.5);
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .categories-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .categories-grid {
    grid-template-columns: 1fr;
  }

  .category-card img {
    height: 220px;
  }
}


/* =========================
   PRODUCTS SECTION
========================= */
.products {
  padding: var(--section-pad) 0;
  background: rgb(var(--surface));
}

.section-title {
  text-align: center;
  font-size: var(--fs-h2);
  margin-bottom: var(--section-title-margin);
  font-family: var(--font-display);
}

/* GRID */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--section-gap);
}

/* CARD */
.product-card {
  background: rgb(var(--surface));
  border-radius: 20px;
  overflow: hidden;
  transition: 0.3s ease;
  border: 1px solid rgb(var(--border) / 0.18);
  box-shadow: var(--shadow-soft);
}

/* IMAGE */
.product-image {
  position: relative;
  overflow: hidden;
}

.product-image img {
  width: 100%;
  height: 260px;
  object-fit: cover;
  transition: transform 0.5s ease;
}

/* WISHLIST */
.wishlist {
  position: absolute;
  top: 15px;
  right: 15px;
  background: rgb(var(--surface));
  padding: 6px 10px;
  border-radius: 50%;
  font-size: 16px;
  cursor: pointer;
  transition: 0.3s ease;
  box-shadow: 0 12px 30px -22px rgba(15, 23, 42, 0.45);
}

.wishlist:hover {
  background: rgb(var(--accent));
  color: #fff;
}

/* OVERLAY */
.product-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.4);
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 0;
  transition: 0.3s ease;
}

/* BUTTON */
.btn-cart {
  padding: 10px 24px;
  border-radius: 30px;
  background: rgb(var(--surface));
  color: rgb(var(--ink-soft));
  text-decoration: none;
  font-size: 14px;
  transform: translateY(10px);
  transition: 0.3s ease;
  border: 1px solid rgb(var(--border) / 0.25);
}

/* INFO */
.product-info {
  padding: 24px;
  text-align: center;
}

.product-info h3 {
  font-size: 16px;
  margin-bottom: 5px;
}

.product-info p {
  color: #777;
}

/* HOVER EFFECTS */
.product-card:hover {
  transform: translateY(-10px);
  box-shadow: var(--shadow-lift);
}

.product-card:hover img {
  transform: scale(1.1);
}

.product-card:hover .product-overlay {
  opacity: 1;
}

.product-card:hover .btn-cart {
  transform: translateY(0);
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .products-grid {
    grid-template-columns: 1fr;
  }
}

/* =========================
   PATTERN LIBRARY
========================= */
.pattern-library {
  padding: var(--section-pad) 0;
  background: linear-gradient(180deg, rgba(250, 247, 244, 0.95) 0%, rgba(248, 250, 252, 0.95) 100%);
}

.pattern-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 30px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.pattern-eyebrow {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.35em;
  color: rgba(15, 23, 42, 0.6);
  margin-bottom: 12px;
}

.pattern-library .section-title {
  text-align: left;
  margin-bottom: 10px;
}

.pattern-subtitle {
  max-width: 520px;
  color: rgba(15, 23, 42, 0.6);
  font-size: 16px;
  line-height: 1.7;
}

.pattern-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.pattern-tab {
  border: 1px solid rgba(15, 23, 42, 0.15);
  padding: 8px 18px;
  border-radius: 999px;
  background: rgba(255,255,255,0.7);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.3s ease;
}

.pattern-tab.active,
.pattern-tab:hover {
  background: rgb(var(--accent));
  color: #fff;
  border-color: rgb(var(--accent));
  box-shadow: 0 16px 30px -18px rgb(var(--accent) / 0.55);
}

.pattern-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--section-gap);
}

.pattern-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: rgb(var(--surface));
  border-radius: 24px;
  overflow: hidden;
  border: 1px solid rgb(var(--border) / 0.2);
  box-shadow: var(--shadow-soft);
  transition: transform 0.35s ease, box-shadow 0.35s ease;
}

.pattern-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-lift);
}

.pattern-image {
  position: relative;
  overflow: hidden;
}

.pattern-image img {
  width: 100%;
  height: 220px;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.pattern-card:hover .pattern-image img {
  transform: scale(1.08);
}

.pattern-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(255,255,255,0.85);
  font-size: 12px;
  font-weight: 600;
  color: rgba(15, 23, 42, 0.85);
}

.pattern-info {
  display: flex;
  flex: 1;
  flex-direction: column;
  padding: 26px;
}

.pattern-info h3 {
  font-size: 18px;
  margin-bottom: 12px;
}

.pattern-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
}

.pattern-copy p {
  margin: 0 0 16px;
  color: rgba(15, 23, 42, 0.66);
  font-size: 14px;
  line-height: 1.65;
}

.pattern-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

.pattern-actions {
  margin-top: auto;
}

.pattern-tags span {
